/**
 * Worker entry point: WebSocket upgrades for realtime rooms go straight to the Durable Objects
 * (Next.js route handlers can't return a 101), everything else to the OpenNext handler.
 * The room verifies the ticket issued by GET /api/realtime/ticket, so nothing is checked here.
 */
import { routeToRoom } from '@kyon/realtime/route';
// @ts-expect-error generated by `opennextjs-cloudflare build`, no type declarations
import handler from './.open-next/worker.js';

const next = handler as ExportedHandler<CloudflareEnv>;

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    // Broadcasts only come from inside (service calls to the DO), never from the internet.
    if (url.pathname.startsWith('/ws/') && !url.pathname.endsWith('/broadcast')) {
      const room = routeToRoom(request, env);
      if (room) return room;
    }
    return (next.fetch as NonNullable<typeof next.fetch>)(request, env, ctx);
  },
} satisfies ExportedHandler<CloudflareEnv>;
